class Solution {
public:
    bool reorderedPowerOf2(int n) {
        string num=to_string(n);
        unordered_map<char,int> ump;
        for(auto it:num)
            ump[it]+=1;
        for(int i=0;i<31;i++)
        {
            unordered_map<char,int> temp;
            string s=to_string(1<<i);
            for(auto it:s)
                temp[it]+=1;
            if(temp==ump)
                return true;
        }
        return false;
    }
};

class Solution(object):
    def reorderedPowerOf2(self, n):
        """
        :type n: int
        :rtype: bool
        """
        def encode_num(num):
            ans = [0 for _ in range(10)]
            while num:
                ans[num % 10] += 1
                num //= 10
            return tuple(ans)

        ans = []
        cur_num = 1
        for _ in range(30):
            ans.append(encode_num(cur_num))
            cur_num = cur_num * 2
        ans = set(ans)
        n_ans = encode_num(n)
        return n_ans in ans
